gbqR(){return"\u0627\u0646\u062a\u062e\u0627\u0628 \u0635\u0646\u062f\u0648\u0642"},
gcQl(){return"\u0628\u0627\u0646\u06a9"},
gcQm(){return"\u0627\u0646\u062a\u062e\u0627\u0628 \u062d\u0633\u0627\u0628 \u0628\u0627\u0646\u06a9\u06cc"},
gcQn(){return"\u0686\u06a9"},
gcQo(){return"\u0627\u0646\u062a\u062e\u0627\u0628 \u06cc\u0627 \u062b\u0628\u062a \u0686\u06a9 \u062f\u0631\u06cc\u0627\u0641\u062a\u06cc"},
gcQk(){return"\u0645\u0628\u0644\u063a"},
gcQi(){return"+ \u0635\u0646\u062f\u0648\u0642"},
