gcQt(){return"\u067e\u0631\u062f\u0627\u062e\u062a\u200c\u0634\u062f\u0647"},
gcQx(){return"\u0645\u0627\u0646\u062f\u0647"},
gcQD(){return"\u062a\u0633\u0648\u06cc\u0647 \u06a9\u0627\u0645\u0644"},
gcQu(){return"\u0645\u0627\u0646\u062f\u0647 \u0631\u0648\u06cc \u062d\u0633\u0627\u0628 \u0645\u0634\u062a\u0631\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u062f"},
