gbqO(){return"\u0633\u0628\u062f \u0641\u0639\u0644\u06cc \u0631\u0627 \u0646\u06af\u0647 \u0645\u06cc\u200c\u062f\u0627\u0631\u062f \u0648 \u0641\u0631\u0648\u0634 \u062f\u06cc\u06af\u0631\u06cc \u0634\u0631\u0648\u0639 \u0645\u06cc\u200c\u06a9\u0646\u062f (Ctrl+N)"},
gbqN(){return"\u0633\u0628\u062f \u0641\u0639\u0644\u06cc \u062e\u0627\u0644\u06cc \u0627\u0633\u062a. \u0627\u0628\u062a\u062f\u0627 \u06a9\u0627\u0644\u0627 \u0627\u0636\u0627\u0641\u0647 \u06a9\u0646\u06cc\u062f \u06cc\u0627 \u0645\u0634\u062a\u0631\u06cc \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646\u06cc\u062f."},
cQf(a){return"\u062d\u062f\u0627\u06a9\u062b\u0631 "+a+" \u0641\u0631\u0648\u0634 \u0628\u0627\u0632 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u062f\u0627\u0634\u062a\u0647 \u0628\u0627\u0634\u06cc\u062f. \u0627\u0628\u062a\u062f\u0627 \u06cc\u06a9\u06cc \u0631\u0627 \u062b\u0628\u062a \u06cc\u0627 \u062d\u0630\u0641 \u06a9\u0646\u06cc\u062f."},
bqP(a){return"\u0641\u0631\u0648\u0634 "+a},
cQg(a,b){return""+a+" \u0642\u0644\u0645 \xb7 "+b},
gcQe(){return"\u062d\u0630\u0641 \u0627\u06cc\u0646 \u0641\u0631\u0648\u0634"},
gcQd(){return"\u0627\u06cc\u0646 \u0641\u0631\u0648\u0634 \u062d\u0630\u0641 \u0634\u0648\u062f\u061f"},
gcQb(){return"\u0627\u06cc\u0646 \u0641\u0631\u0648\u0634 \u0646\u06af\u0647\u200c\u062f\u0627\u0634\u062a\u0647\u200c\u0634\u062f\u0647 \u0648 \u0627\u0642\u0644\u0627\u0645 \u0622\u0646 \u062d\u0630\u0641 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f \u0648 \u0642\u0627\u0628\u0644 \u0628\u0627\u0632\u06af\u0634\u062a \u0646\u06cc\u0633\u062a."},
gcQc(){return"\u062d\u0630\u0641"},
gcQa(){return"\u0645\u0634\u062a\u0631\u06cc \u0646\u0627\u0634\u0646\u0627\u0633"},
gbzv(){return"\u062a\u0646\u0638\u06cc\u0645\u0627\u062a Redis Cache"},
gbzw(){return"\u067e\u06cc\u06a9\u0631\u0628\u0646\u062f\u06cc Redis \u0628\u0631\u0627\u06cc \u0628\u0647\u0628\u0648\u062f \u0639\u0645\u0644\u06a9\u0631\u062f \u0648 \u06a9\u0627\u0647\u0634 \u0628\u0627\u0631 \u062f\u06cc\u062a\u0627\u0628\u06cc\u0633"},
gb03(){return"\u0641\u0627\u06cc\u0631\u0648\u0627\u0644 \u0646\u0631\u0645\u200c\u0627\u0641\u0632\u0627\u0631"},
gbzc(){return"\u0642\u0648\u0627\u0646\u06cc\u0646 \u0627\u062c\u0627\u0632\u0647/\u0631\u062f IP\u060c \u0633\u0642\u0641 \u0646\u0631\u062e \u0645\u0633\u06cc\u0631 (\u062f\u06cc\u062a\u0627\u0628\u06cc\u0633)\u060c \u0628\u0646 \u0645\u0648\u0642\u062a\u060c \u0644\u0627\u06af \u0648 \u06af\u0632\u0627\u0631\u0634"},
gcym(){return"\u0642\u0648\u0627\u0646\u06cc\u0646"},
